using RailwayWebBuilderCore.Enums;

namespace RailwayWebBuilderCore._SiteData.ModelRailways.Layouts;

internal class Kinlochewe : LayoutBase
{
    public Kinlochewe()
    {
        Name = LayoutNamesEnums.Kinlochewe;
        Description = "This layout depicts Kinlochewe as it would have been had the Skye and Dingwall Railway's proposed branch line ever reached the town, set in the late 1970s and 1980s. The terminus station uses similar run-round procedures to those employed at Kyle of Lochalsh, the arriving locomotive propelling its train to a point where, after uncoupling, it can run round - and on occasion a parcels van is detached and propelled into the bay platform with the Royal Mail staff eagerly awaiting it. The line follows the same operating procedures as the Far North line at Georgemas Junction, where an out-stationed locomotive attaches to a portion of the train, Kinlochewe fictionally assuming this would have taken place at Achnasheen. Freight occasionally calls, in the form of an Inverness to Kyle of Lochalsh working carrying general merchandise, oil tanks with fuel for the ferries, and cement for the oil rig construction facility at Stromeferry. The town street is quite detailed - and yes, palm trees do grow on the west coast of Scotland thanks to the Gulf Stream. The former goods shed is now used as a garage, and the station features a private platform accessed through ornamental gates, its construction having been a condition of the sale of the land for the station site by a wealthy landowner who required his own platform.";
    }
}
